import React from 'react';
import {
  Box,
  Grid,
  Paper,
  Typography,
  Card,
  CardContent,
  List,
  ListItem,
  ListItemText,
  Chip,
  CircularProgress,
  Link,
} from '@mui/material';
import {
  Restaurant,
  TrendingUp,
  Warning,
  Assessment,
} from '@mui/icons-material';
import { useQuery } from 'react-query';
import { useNavigate } from 'react-router-dom';
import { api } from '../../services/api';
import { useAuth } from '../../contexts/AuthContext';

interface DashboardStats {
  totalOrders: number;
  pendingOrders: number;
  availableTables: number;
  totalTables: number;
  lowStockItems: number;
  todayRevenue: number;
}

interface Order {
  id: string;
  table: { number: number };
  status: string;
  total: number;
  createdAt: string;
  items: Array<{
    product: { name: string };
    quantity: number;
  }>;
}

export default function Dashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();

  const { data: stats, isLoading: statsLoading } = useQuery<DashboardStats>(
    'dashboard-stats',
    async () => {
      const [ordersRes, ingredientsRes] = await Promise.all([
        api.get('/orders'),
        api.get('/ingredients'),
      ]);

      const orders = ordersRes.data;
      const ingredients = ingredientsRes.data;

      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayOrders = orders.filter((order: Order) => {
        const orderDate = new Date(order.createdAt);
        orderDate.setHours(0, 0, 0, 0);
        return orderDate.getTime() === today.getTime() && order.status === 'DELIVERED';
      });

      const lowStockItems = ingredients.filter((ingredient: any) => 
        ingredient.currentStock <= ingredient.minStock
      );

      return {
        totalOrders: orders.length,
        pendingOrders: orders.filter((order: Order) => 
          ['PENDING', 'PREPARING', 'READY'].includes(order.status)
        ).length,
        availableTables: 0,
        totalTables: 0,
        lowStockItems: lowStockItems.length,
        todayRevenue: todayOrders.reduce((sum: number, order: Order) => sum + order.total, 0),
      };
    },
    {
      refetchInterval: 30000, // Atualizar a cada 30 segundos
    }
  );

  const { data: recentOrders, isLoading: ordersLoading } = useQuery<Order[]>(
    'recent-orders',
    async () => {
      const response = await api.get('/orders?limit=5');
      return response.data.slice(0, 5);
    },
    {
      refetchInterval: 10000, // Atualizar a cada 10 segundos
    }
  );

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PENDING': return 'warning';
      case 'PREPARING': return 'info';
      case 'READY': return 'success';
      case 'DELIVERED': return 'default';
      case 'CANCELLED': return 'error';
      default: return 'default';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'PENDING': return 'Pendente';
      case 'PREPARING': return 'Preparando';
      case 'READY': return 'Pronto';
      case 'DELIVERED': return 'Entregue';
      case 'CANCELLED': return 'Cancelado';
      default: return status;
    }
  };

  if (statsLoading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Dashboard
      </Typography>
      <Typography variant="body1" color="text.secondary" gutterBottom>
        Bem-vindo(a), {user?.name}! Aqui está um resumo do seu restaurante.
      </Typography>

      <Grid container spacing={3} sx={{ mt: 2 }}>
        {/* Cards de Estatísticas */}
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center">
                <Restaurant color="primary" sx={{ mr: 2 }} />
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Pedidos Ativos
                  </Typography>
                  <Typography variant="h4">
                    {stats?.pendingOrders || 0}
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center">
                <Assessment color="primary" sx={{ mr: 2 }} />
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Total de Pedidos
                  </Typography>
                  <Typography variant="h4">
                    {stats?.totalOrders || 0}
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center">
                <TrendingUp color="primary" sx={{ mr: 2 }} />
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Receita Hoje
                  </Typography>
                  <Typography variant="h4">
                    R$ {stats?.todayRevenue?.toFixed(2) || '0.00'}
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center">
                <Warning color={stats?.lowStockItems ? 'error' : 'primary'} sx={{ mr: 2 }} />
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Estoque Baixo
                  </Typography>
                  <Typography variant="h4" color={stats?.lowStockItems ? 'error' : 'inherit'}>
                    {stats?.lowStockItems || 0}
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Pedidos Recentes */}
        <Grid item xs={12} md={8}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              Pedidos Recentes
            </Typography>
            {ordersLoading ? (
              <Box display="flex" justifyContent="center" p={3}>
                <CircularProgress />
              </Box>
            ) : (
              <List>
                {recentOrders?.map((order) => (
                  <ListItem key={order.id} divider>
                    <ListItemText
                      primary={`Pedido #${order.orderNumber || order.id.slice(-4)} - ${order.customerName || 'Cliente'} - R$ ${order.total.toFixed(2)}`}
                      secondary={
                        <Box>
                          <Typography variant="body2" color="text.secondary">
                            {order.orderItems?.map(item => 
                              `${item.quantity}x ${item.product.name}`
                            ).join(', ') || 'Sem itens'}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            {new Date(order.createdAt).toLocaleString('pt-BR')}
                          </Typography>
                        </Box>
                      }
                    />
                    <Chip
                      label={getStatusText(order.status)}
                      color={getStatusColor(order.status) as any}
                      size="small"
                    />
                  </ListItem>
                ))}
                {(!recentOrders || recentOrders.length === 0) && (
                  <ListItem>
                    <ListItemText
                      primary="Nenhum pedido encontrado"
                      secondary="Os pedidos aparecerão aqui quando forem criados"
                    />
                  </ListItem>
                )}
              </List>
            )}
          </Paper>
        </Grid>

        {/* Ações Rápidas */}
        <Grid item xs={12} md={4}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="h6" gutterBottom>
              Ações Rápidas
            </Typography>
            <Box display="flex" flexDirection="column" gap={1}>
              <Link
                component="button"
                variant="body2"
                onClick={() => navigate('/orders')}
                sx={{ textAlign: 'left', textDecoration: 'none' }}
              >
                • Novo Pedido
              </Link>
              <Link
                component="button"
                variant="body2"
                onClick={() => navigate('/products')}
                sx={{ textAlign: 'left', textDecoration: 'none' }}
              >
                • Gerenciar Produtos
              </Link>
              {user?.role === 'ADMIN' && (
                <>
                  <Link
                    component="button"
                    variant="body2"
                    onClick={() => navigate('/products')}
                    sx={{ textAlign: 'left', textDecoration: 'none' }}
                  >
                    • Adicionar Produto
                  </Link>
                  <Link
                    component="button"
                    variant="body2"
                    onClick={() => navigate('/ingredients')}
                    sx={{ textAlign: 'left', textDecoration: 'none' }}
                  >
                    • Controle de Estoque
                  </Link>
                  <Link
                    component="button"
                    variant="body2"
                    onClick={() => navigate('/reports')}
                    sx={{ textAlign: 'left', textDecoration: 'none' }}
                  >
                    • Relatórios
                  </Link>
                </>
              )}
              <Link
                component="button"
                variant="body2"
                onClick={() => navigate('/orders')}
                sx={{ textAlign: 'left', textDecoration: 'none' }}
              >
                • Ver Todos os Pedidos
              </Link>
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
}
